//   .param .u64 y_ptr   - pointer to output __half tensor
//   .param .u32 batch   - number of batches (grid.x)
//   .param .u32 features
//   .param .u32 dim1
//   .param .u32 dim2
// ---------------------------------------------------------------
.visible .entry layernorm_kernel(
    .param .u64 x_ptr,
    .param .u64 y_ptr,
    .param .u32 batch,
    .param .u32 features,
    .param .u32 dim1,
    .param .u32 dim2
)
{
    // ------------------------------
    // thread / block identifiers
    // ------------------------------
    .reg .u32   %tid, %ntid, %bid;
    mov.u32 %tid,  %tid.x;
    mov.u32 %ntid, %ntid.x;          // blockDim.x (fixed 256)
    mov.u32 %bid,  %ctaid.x;         // batch index

    // ------------------------------
    // load kernel parameters
    // ------------------------------
    .reg .u64   %x_ptr, %y_ptr;
    .reg .u32   %features, %dim1, %dim2, %N;
    ld.param.u64 %x_ptr,   [x_ptr];
    ld.param.u64 %y_ptr,   [y_ptr];
    ld.param.u32 %features,[features];
    ld.param.u32 %dim1,    [dim1];
    ld.param.u32 %dim2,    [dim2];

    // N = features * dim1 * dim2
    mul.lo.u32 %N, %features, %dim1;
    mul.lo.u32 %N, %N, %dim2;

    // ------------------------------
    // compute base addresses for this batch
    // ------------------------------
    .reg .u64 %batch_offset, %in_base, %out_base;
    cvt.u64.u32 %batch_offset, %bid;
    mul.lo.u64 %batch_offset, %batch_offset, %N;          // offset in elements
    mul.wide.u32 %in_base,  %batch_offset, 2;             // half = 2 bytes
    add.u64 %in_base, %x_ptr, %in_base;
    mul.wide.u32 %out_base, %batch_offset, 2;
    add.u64 %out_base, %y_ptr, %out_base;

    // -------------------------------------------------
    // First pass: compute mean (sum of elements)
    // -------------------------------------------------
    .reg .f32 %sum, %temp;
    mov.f32 %sum, 0f00000000;
    .reg .u32 %idx;
    mov.u32 %idx, %tid;

