    .reg .u64 %addr;
    mul.wide.u32 %addr, %idx, 2;
    add.u64 %addr, %in_base, %addr;
    .reg .u16 %hval;
    ld.global.u16 %hval, [%addr];
    // convert to float
    cvt.f32.f16 %temp, %hval;
    add.f32 %sum, %sum, %temp;
    // next
    add.u32 %idx, %idx, %ntid;
    bra.uni L_sum_loop;
L_sum_done:

    // ------------------------------
    // reduction in shared memory
    // ------------------------------
    .shared .align 4 .b8 sdata[1024];          // 256 * 4 bytes
    .reg .u64 %saddr;
