    .reg .f32 %mean;
    .reg .u64 %saddr0;
    mul.wide.u32 %saddr0, 0, 4;
    add.u64 %saddr0, sdata, %saddr0;
    ld.shared.f32 %sum, [%saddr0];
    cvt.f32.u32 %temp, %N;
    div.f32 %mean, %sum, %temp;

