    add.u64 %saddr, sdata, %saddr;
    st.shared.f32 [%saddr], %var_sum;
    bar.sync 0;

    mov.u32 %stride, %ntid;
L_reduce_var:
    shr.u32 %stride, %stride, 1;
    setp.eq.u32 %p, %stride, 0;
    @%p bra L_reduce_var_done;

    setp.lt.u32 %p2, %tid, %stride;
    @%p2 {
        // load a = sdata[tid]
        mul.wide.u32 %saddr, %tid, 4;
        add.u64 %saddr, sdata, %saddr;
        ld.shared.f32 %temp, [%saddr];
