        add.u32 %t2, %tid, %stride;
        mul.wide.u32 %saddr, %t2, 4;
        add.u64 %saddr, sdata, %saddr;
        ld.shared.f32 %sdata0, [%saddr];
        add.f32 %temp, %temp, %sdata0;
        // store back
        mul.wide.u32 %saddr, %tid, 4;
        add.u64 %saddr, sdata, %saddr;
        st.shared.f32 [%saddr], %temp;
    }
    bar.sync 0;
    bra.uni L_reduce_var;
L_reduce_var_done:

    // variance = sdata[0] / N
    .reg .f32 %var;
    ld.shared.f32 %var_sum, [%saddr0];   // reuse address of element 0
    div.f32 %var, %var_sum, %temp;      // %temp still holds N as float

