    .reg .f32 %eps, %inv_std;
    mov.f32 %eps, 0.000010000000f;       // epsilon = 1e-5
    add.f32 %var, %var, %eps;
    rsqrt.approx.f32 %inv_std, %var;

    // -------------------------------------------------
    // Final pass: write normalized output
    // -------------------------------------------------
    mov.u32 %idx, %tid;
L_out_loop:
    setp.ge.u32 %p, %idx, %N;
    @%p bra L_out_done;
