    mul.wide.u32 %addr, %idx, 2;
    add.u64 %addr, %in_base, %addr;
    ld.global.u16 %hval, [%addr];
    cvt.f32.f16 %temp, %hval;
    sub.f32 %temp, %temp, %mean;
    mul.f32 %temp, %temp, %inv_std;
    // convert back to half
    cvt.rn.f16.f32 %hval, %temp;
    // store
    mul.wide.u32 %addr, %idx, 2;
    add.u64 %addr, %out_base, %addr;
    st.global.u16 [%addr], %hval;
    add.u32 %idx, %idx, %ntid;
    bra.uni L_out_loop;
L_out_done:
    ret;
}
